"""Drives the victim's eval runner: `python -m <eval_module> --task <id> --seed <n>`.

The runner prints one JSON object (passed, cost, latency, tokens, trace_id). Culprit tags every
victim trace through CULPRIT_RUN_ID, COMMIT_SHA, TASK_ID and REPETITION.
"""

from __future__ import annotations

import json
import re
import subprocess
import time
from collections.abc import Mapping
from pathlib import Path
from typing import Any

from dotenv import dotenv_values

from culprit.ledger import TaskRun
from culprit.providers import Provider
from culprit.sandbox import clean_env, python_of


def victim_env(repo: Path, victim: Provider | None = None) -> dict[str, str]:
    """Culprit's environment overlaid with the victim's own (gitignored) `.env`, if present.

    The run's victim provider and model go on top, so a `.env` can't switch models mid-run. Old
    victim commits need `LLM_PROVIDER` and `VICTIM_MODEL` set explicitly; the price lets a victim
    that doesn't know the model still report cost (RefundDesk reads VICTIM_PRICE_IN/OUT).
    """
    env = clean_env()
    env_file = repo / ".env"
    if env_file.exists():
        env.update({k: v for k, v in dotenv_values(env_file).items() if v is not None})
    if victim is not None:
        env |= {"LLM_PROVIDER": victim.name, "VICTIM_MODEL": victim.model}
        if victim.price is not None:
            env |= {"VICTIM_PRICE_IN": str(victim.price[0]), "VICTIM_PRICE_OUT": str(victim.price[1])}
    return env


def discover_tasks(suite_dir: Path) -> list[str]:
    """Task ids are the file stems directly in the suite directory (subdirectories such as heldout/ excluded)."""
    if not suite_dir.is_dir():
        raise FileNotFoundError(f"suite directory {suite_dir} not found")
    return sorted(
        p.stem for p in suite_dir.iterdir()
        if p.is_file() and not p.name.startswith(("_", ".")) and p.suffix in {".json", ".yaml", ".yml", ".py", ".toml"}
    )


def _parse_output(stdout: str) -> dict[str, Any]:
    for line in reversed(stdout.strip().splitlines()):
        line = line.strip()
        if line.startswith("{"):
            try:
                return json.loads(line)
            except json.JSONDecodeError:
                continue
    try:
        return json.loads(stdout)
    except json.JSONDecodeError as exc:
        raise ValueError("eval runner printed no JSON object") from exc


def _tokens(raw: Any) -> tuple[int | None, int | None]:
    if isinstance(raw, Mapping):
        tin = raw.get("in", raw.get("input", raw.get("input_tokens", raw.get("prompt_tokens"))))
        tout = raw.get("out", raw.get("output", raw.get("output_tokens", raw.get("completion_tokens"))))
        return (None if tin is None else int(tin)), (None if tout is None else int(tout))
    if isinstance(raw, int | float):
        return int(raw), None
    return None, None


# A victim run that failed for one of these reasons says nothing about the commit under test, so
# it must never count as a failed task. Transient errors are retried; fatal ones stop the run.
TRANSIENT_ERROR = re.compile(
    r"RateLimitError|APIConnectionError|APITimeoutError|InternalServerError|OverloadedError|"
    r"ServiceUnavailableError|overloaded_error|rate_limit_error|Error code: (?:429|5\d\d)|"
    r"^timeout after \d+s$|eval runner printed no JSON"
)
FATAL_ERROR = re.compile(
    r"AuthenticationError|PermissionDeniedError|ConfigError|credit balance|Could not resolve authentication|"
    r"NotFoundError: Error code: 404 .*model"
)


def infra_failure(tr: TaskRun) -> str | None:
    """'transient' or 'fatal' when the run failed for infrastructure reasons, else None."""
    if tr.passed or not tr.error:
        return None
    if FATAL_ERROR.search(tr.error):
        return "fatal"
    if TRANSIENT_ERROR.search(tr.error):
        return "transient"
    return None


def run_task(
    worktree: Path, base_env: Mapping[str, str], eval_module: str, task_id: str, repetition: int,
    *, run_id: str, commit_sha: str, timeout_s: int,
) -> TaskRun:
    env = dict(base_env) | {
        "CULPRIT_RUN_ID": run_id,
        "COMMIT_SHA": commit_sha,
        "TASK_ID": task_id,
        "REPETITION": str(repetition),
    }
    cmd = [str(python_of(worktree)), "-m", eval_module, "--task", task_id, "--seed", str(repetition)]
    started = time.monotonic()
    try:
        proc = subprocess.run(cmd, cwd=worktree, env=env, capture_output=True, text=True, timeout=timeout_s)
    except subprocess.TimeoutExpired:
        return TaskRun(task_id, repetition, False, None, timeout_s * 1000.0, None, None, None,
                       f"timeout after {timeout_s}s")
    wall_ms = (time.monotonic() - started) * 1000.0
    try:
        out = _parse_output(proc.stdout)
    except ValueError as exc:
        tail = (proc.stderr or proc.stdout)[-400:]
        return TaskRun(task_id, repetition, False, None, wall_ms, None, None, None,
                       f"exit {proc.returncode}: {exc}: {tail}")
    tin, tout = _tokens(out.get("tokens"))
    # `latency_ms` is taken as-is; a bare `latency` is the runner's seconds value.
    if out.get("latency_ms") is not None:
        latency_ms = float(out["latency_ms"])
    elif out.get("latency") is not None:
        latency_ms = float(out["latency"]) * 1000.0
    else:
        latency_ms = wall_ms
    return TaskRun(
        task_id=task_id,
        repetition=repetition,
        passed=bool(out.get("passed")),
        cost_usd=None if out.get("cost") is None else float(out["cost"]),
        latency_ms=latency_ms,
        tokens_in=tin,
        tokens_out=tout,
        trace_id=out.get("trace_id"),
        error=out.get("error"),
    )

def leak_filter(text: str, refs: list[str]) -> tuple[str, int]:
    patterns = LEAK_PATTERNS + [re.compile(rf"(?<![\w/.-]){re.escape(r)}(?![\w/-])") for r in refs]
    kept, removed = [], 0
    for line in text.splitlines():
        if any(p.search(line) for p in patterns):
            removed += 1
        else:
            kept.append(line)
    return "\n".join(kept), removed


def explain(repo: Path, sha: str, *flags: str, timeout_s: int = 120) -> tuple[int, str]:
    proc = subprocess.run(
        ["entire", "checkpoint", "explain", sha, "--no-pager", *flags],
        cwd=repo, capture_output=True, text=True, timeout=timeout_s,
    )
    return proc.returncode, ANSI.sub("", proc.stdout + proc.stderr)


def intent_line(explain_text: str) -> str:
    """The `## Intent` section of `entire checkpoint explain`; empty if it is a harness tag or placeholder."""
    match = re.search(r"## Intent\s*\n(.*?)\n## ", explain_text, re.DOTALL)
    intent = match.group(1).strip() if match else ""
    return "" if not intent or intent.startswith(("<", "*(")) else intent  # tag or "*(no prompt recorded)*"


def session_prompts(repo: Path, sha: str, limit_chars: int = 4000) -> list[str]:
    """Genuine user prompts from the checkpoint's own session transcript (`--transcript` JSONL).

    Entire's Intent can be a harness event (e.g. `<task-notification>`) when the commit's turn was
    not started by the user, so the session's typed prompts are the fallback source of intent.
    """
    code, out = explain(repo, sha, "--transcript")
    if code != 0:
        return []
    prompts: list[str] = []
    for line in out.splitlines():
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            continue
        content = event.get("message", {}).get("content") if event.get("type") == "user" else None
        if isinstance(content, str):
            text = re.sub(r"</?pasted_content[^>]*>", "", content).strip()
            if text and not text.startswith("<"):
                prompts.append(text[:limit_chars])
    return prompts


def commit_intent(repo: Path, sha: str) -> Intent:
    refs = ref_names(repo)
    try:
        code, out = explain(repo, sha)
    except (OSError, subprocess.TimeoutExpired) as exc:
        code, out = -1, f"entire unavailable: {exc}"
    match = re.search(r"Checkpoint\s+([0-9A-Z]{20,})", out)
    if code == 0 and match:
        intent = intent_line(out)
        source = "entire"
        if not intent:
            intent = "\n\n".join(session_prompts(repo, sha))
            source = "entire: session prompts (Intent field empty or a harness event)"
        text, removed = leak_filter(f"Intent:\n{intent}\n\nCheckpoint context:\n{out}", refs)
        return Intent(bool(intent.strip()), match.group(1), text, removed, source)
    reason = out.strip().splitlines()[0] if out.strip() else f"exit {code}"
    # The diff is code, not Entire text, so only the commit message goes through the filter.
    msg, removed = leak_filter(message(repo, sha), refs)
    return Intent(False, None, f"Commit message:\n{msg}\n\nDiff:\n{diff(repo, sha)}", removed, f"fallback: {reason}")
# Blockers, unsupported features and known discrepancies

Each entry lists what the PRD assumed, what the tool actually supports (sources in `docs/research.md`), and the fallback we chose.

## Known discrepancies

### neatlogs cost for `claude-sonnet-5-5` differs from the list price

- **Observed:** for one call of 131 input and 18 output tokens, neatlogs reported `costUsd = 0.000663` (trace `ffdf497989747bf30856935f187e6013`, LLM span). That matches $3/$15 per MTok.
- **List price:** Anthropic's published list price for `claude-sonnet-5-5` is $2/$10 per MTok (cached 2026-10-06), which gives $0.000442 for the same call.
- **Decision:** Culprit's ledger (`culprit.llm.ANTHROPIC_PRICES`, $2/$10) is the only source of truth for cost, `export-costs` and cfo.ai. neatlogs' cost fields are not used in any cost number. Evidence tables that show neatlogs costs label them "neatlogs-reported, not used".

## Unsupported or changed vs the PRD

| PRD assumption | Reality | Fallback |
|---|---|---|
| Look up victim traces by `run_id` / `commit_sha` metadata (§14.1) | The read API and CLI can't filter on, or return, custom span attributes | Culprit stores every trace ID in the ledger. Its own traces use `session_id = run_id`, and run context also goes into each span's input JSON so readback can verify it |
| Read the current trace ID in code (§14.1 open question) | No getter in the SDK | `inject_trace_context()` W3C traceparent; verified to equal the read API's `traceId` |
| Investigate on v1 benchmark runs (§14.1) | Dashboard only; no API or CLI | Use Investigate by hand in the dashboard; record findings and screenshots in `evidence/` |
| Detection "`status: failed` followed by `issue_refund`" (§14.1) | Detections are per-span regex or conditional rules; a cross-span sequence can't be expressed in one rule | Not built yet (M4). Plan: regex on `issue_refund` tool spans plus a Culprit-side sequence check |
| `entire checkpoint explain` intent | The `## Intent` field can be a harness event (`<task-notification>`) or `*(no prompt recorded)*`, and `--json` carries no intent | Culprit reads the session's typed prompts from `--transcript` when Intent is a placeholder; commit message and diff when there is no checkpoint |
| OpenRouter provider | Dropped at first, then reinstated as the fallback (Sat evening) | Anthropic (Sonnet 5.5) when `ANTHROPIC_API_KEY` is set, otherwise OpenRouter (GLM 5.3). Culprit picks the victim model once per run and records it, so all commits are judged by the same model |

